'use client'

import * as React from 'react'

import { cn } from '@/lib/utils'

export interface LedgerRow {
  id: string
  date: string
  reference: string
  accountCode: string
  accountName: string
  currency: 'AUD' | 'USD' | 'EUR' | 'GBP'
  debit: number
  credit: number
  balance: number
}

export interface MultiCurrencyLedgerProps {
  rows: LedgerRow[]
  onSort?: (column: keyof LedgerRow, direction: 'asc' | 'desc') => void
  onCellEdit?: (rowId: string, column: 'accountCode' | 'accountName', value: string) => void
  onCellFocus?: (rowId: string, column: keyof LedgerRow) => void
  className?: string
}

type LedgerColumn = {
  key: keyof LedgerRow
  label: string
  className: string
  align?: 'right'
}

const columns: LedgerColumn[] = [
  { key: 'date', label: 'Date', className: 'w-[108px]' },
  { key: 'reference', label: 'Transaction / reference', className: 'w-[178px]' },
  { key: 'accountCode', label: 'Account', className: 'w-[90px]' },
  { key: 'accountName', label: 'Account name', className: 'min-w-[210px]' },
  { key: 'currency', label: 'CCY', className: 'w-[68px]' },
  { key: 'debit', label: 'Debit', className: 'w-[132px]', align: 'right' },
  { key: 'credit', label: 'Credit', className: 'w-[132px]', align: 'right' },
  { key: 'balance', label: 'Running balance', className: 'w-[154px]', align: 'right' }
]

function money(value: number, currency: LedgerRow['currency']) {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol',
    minimumFractionDigits: 2
  }).format(value)
}

function compareRows(a: LedgerRow, b: LedgerRow, key: keyof LedgerRow) {
  const left = a[key]
  const right = b[key]
  if (typeof left === 'number' && typeof right === 'number') return left - right
  return String(left).localeCompare(String(right))
}

export function MultiCurrencyLedger({ rows, onSort, onCellEdit, onCellFocus, className }: MultiCurrencyLedgerProps) {
  const [data, setData] = React.useState(rows)
  const [sorting, setSorting] = React.useState<{ key: keyof LedgerRow; direction: 'asc' | 'desc' }>({ key: 'date', direction: 'desc' })
  const [focusedCell, setFocusedCell] = React.useState({ row: 0, column: 0 })
  const [editing, setEditing] = React.useState<{ rowId: string; column: 'accountCode' | 'accountName'; value: string } | null>(null)
  const cellRefs = React.useRef(new Map<string, HTMLTableCellElement>())

  React.useEffect(() => setData(rows), [rows])

  const sortedRows = React.useMemo(() => {
    const next = [...data].sort((a, b) => compareRows(a, b, sorting.key))
    return sorting.direction === 'asc' ? next : next.reverse()
  }, [data, sorting])

  const updateSort = (key: keyof LedgerRow) => {
    const direction = sorting.key === key && sorting.direction === 'asc' ? 'desc' : 'asc'
    setSorting({ key, direction })
    onSort?.(key, direction)
  }

  const focusCell = (row: number, column: number) => {
    const boundedRow = Math.max(0, Math.min(sortedRows.length - 1, row))
    const boundedColumn = Math.max(0, Math.min(columns.length - 1, column))
    setFocusedCell({ row: boundedRow, column: boundedColumn })
    window.requestAnimationFrame(() => cellRefs.current.get(`${boundedRow}:${boundedColumn}`)?.focus())
  }

  const commitEdit = () => {
    if (!editing) return
    setData((current) => current.map((row) => row.id === editing.rowId ? { ...row, [editing.column]: editing.value } : row))
    onCellEdit?.(editing.rowId, editing.column, editing.value)
    setEditing(null)
  }

  return (
    <section aria-label="Multi-currency general ledger" className={cn('flex min-h-0 flex-col border bg-card', className)}>
      <header className="flex min-h-10 items-center border-b px-3">
        <div className="min-w-0 flex-1">
          <h2 className="text-[13px] font-semibold tracking-tight">General ledger</h2>
          <p className="text-[11px] text-muted-foreground">Double-entry journal · Base currency AUD</p>
        </div>
        <div className="financial-data flex gap-4 text-[11px] text-muted-foreground">
          <span>{rows.length.toLocaleString('en-AU')} entries</span>
          <span>FY 2026–27</span>
        </div>
      </header>

      <div className="scrollbar-thin min-h-0 flex-1 overflow-auto" role="region" aria-label="Ledger entries" tabIndex={0}>
        <table className="w-full min-w-[1072px] table-fixed border-collapse text-left text-[11px]">
          <thead className="sticky top-0 z-10 bg-muted">
            <tr className="h-8 border-b">
              {columns.map((column) => {
                const isSorted = sorting.key === column.key
                return (
                  <th key={column.key} scope="col" className={cn('border-r px-2 font-semibold last:border-r-0', column.className, column.align === 'right' && 'text-right')}>
                    <button
                      type="button"
                      onClick={() => updateSort(column.key)}
                      className={cn('group inline-flex h-7 max-w-full items-center gap-1 text-[10px] uppercase tracking-[0.06em] text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring', column.align === 'right' && 'ml-auto')}
                    >
                      <span className="truncate">{column.label}</span>
                      <span aria-hidden className={cn('text-[8px] transition-transform', !isSorted && 'opacity-25', isSorted && sorting.direction === 'asc' && 'rotate-180')}>▼</span>
                      <span className="sr-only">{isSorted ? `, sorted ${sorting.direction}ending` : ', activate to sort'}</span>
                    </button>
                  </th>
                )
              })}
            </tr>
          </thead>
          <tbody>
            {sortedRows.map((row, rowIndex) => (
              <tr key={row.id} className="h-8 border-b bg-card hover:bg-muted/45">
                {columns.map((column, columnIndex) => {
                  const key = `${rowIndex}:${columnIndex}`
                  const isFocused = focusedCell.row === rowIndex && focusedCell.column === columnIndex
                  const isEditable = column.key === 'accountCode' || column.key === 'accountName'
                  const isEditing = editing?.rowId === row.id && editing.column === column.key
                  let value: React.ReactNode = row[column.key]

                  if (column.key === 'debit' || column.key === 'credit') value = row[column.key] === 0 ? '' : money(row[column.key], row.currency)
                  if (column.key === 'balance') value = money(row.balance, row.currency)

                  return (
                    <td
                      key={column.key}
                      ref={(node) => {
                        if (node) cellRefs.current.set(key, node)
                        else cellRefs.current.delete(key)
                      }}
                      tabIndex={isFocused ? 0 : -1}
                      aria-label={`${column.label}, ${String(value)}`}
                      onFocus={() => {
                        setFocusedCell({ row: rowIndex, column: columnIndex })
                        onCellFocus?.(row.id, column.key)
                      }}
                      onDoubleClick={() => {
                        if (isEditable) setEditing({ rowId: row.id, column: column.key as 'accountCode' | 'accountName', value: String(row[column.key]) })
                      }}
                      onKeyDown={(event) => {
                        if (event.key === 'ArrowDown') { event.preventDefault(); focusCell(rowIndex + 1, columnIndex) }
                        if (event.key === 'ArrowUp') { event.preventDefault(); focusCell(rowIndex - 1, columnIndex) }
                        if (event.key === 'ArrowRight') { event.preventDefault(); focusCell(rowIndex, columnIndex + 1) }
                        if (event.key === 'ArrowLeft') { event.preventDefault(); focusCell(rowIndex, columnIndex - 1) }
                        if ((event.key === 'Enter' || event.key === 'F2') && isEditable) {
                          event.preventDefault()
                          setEditing({ rowId: row.id, column: column.key as 'accountCode' | 'accountName', value: String(row[column.key]) })
                        }
                      }}
                      className={cn(
                        'h-8 overflow-hidden border-r px-2 align-middle outline-none last:border-r-0 focus-visible:relative focus-visible:z-[1] focus-visible:ring-1 focus-visible:ring-inset focus-visible:ring-info',
                        column.className,
                        column.align === 'right' && 'financial-data text-right',
                        ['date', 'reference', 'accountCode', 'currency'].includes(column.key) && 'financial-data',
                        column.key === 'balance' && 'font-semibold',
                        (column.key === 'debit' && row.debit > 0) && 'text-destructive',
                        (column.key === 'credit' && row.credit > 0) && 'text-success'
                      )}
                    >
                      {isEditing ? (
                        <input
                          autoFocus
                          value={editing.value}
                          onChange={(event) => setEditing({ ...editing, value: event.target.value })}
                          onBlur={commitEdit}
                          onKeyDown={(event) => {
                            event.stopPropagation()
                            if (event.key === 'Enter') commitEdit()
                            if (event.key === 'Escape') setEditing(null)
                          }}
                          className="h-7 w-full border-0 bg-background px-1 text-[11px] outline-none ring-1 ring-inset ring-info"
                        />
                      ) : (
                        <span className={cn('block truncate', column.key === 'currency' && 'text-muted-foreground')}>{value}</span>
                      )}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <footer className="flex h-8 shrink-0 items-center gap-4 border-t bg-muted/30 px-3 text-[10px] text-muted-foreground">
        <span>Arrow keys move cell focus</span><span>Enter or double-click edits account fields</span><span className="ml-auto financial-data">AUD · USD · EUR · GBP</span>
      </footer>
    </section>
  )
}
