import * as React from 'react'
import { Badge, type BadgeProps } from './badge'
import { cn } from '@/lib/utils'

export type FinancialStatus = 'neutral' | 'paid' | 'reconciled' | 'overdue' | 'pending' | 'draft' | 'unmatched'

const statusTone: Record<FinancialStatus, NonNullable<BadgeProps['tone']>> = {
  neutral: 'neutral',
  paid: 'credit',
  reconciled: 'credit',
  overdue: 'debit',
  pending: 'suspense',
  draft: 'suspense',
  unmatched: 'suspense'
}

export interface StatusBadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  status?: FinancialStatus
  dot?: boolean
}

function StatusBadge({ className, status = 'neutral', dot = true, children, ...props }: StatusBadgeProps) {
  return (
    <Badge className={cn(className)} tone={statusTone[status]} indicator={dot} {...props}>
      {children}
    </Badge>
  )
}

export { StatusBadge, statusTone as statusBadgeVariants }
