'use client'

import * as React from 'react'

import { Button } from '@/components/ui/button'
import { StatusBadge } from '@/components/ui/status-badge'
import { cn } from '@/lib/utils'

export type ReconciliationAction = 'Match' | 'Transfer' | 'Rule' | 'Discuss'

export interface BankTransaction {
  id: string
  date: string
  description: string
  amount: number
  currency: string
  action: ReconciliationAction
  accountCode: string
  accountName: string
  confidence: number
  state?: 'suggested' | 'manual' | 'pending'
}

export interface BankReconciliationProps {
  transactions: BankTransaction[]
  onMatch?: (transactionId: string, accountCode: string) => void
  onAccountChange?: (transactionId: string, accountCode: string) => void
  onActionChange?: (transactionId: string, action: ReconciliationAction) => void
  className?: string
}

const accountOptions = [
  ['200', 'Sales Revenue'],
  ['221', 'Professional Services'],
  ['310', 'GST Collected'],
  ['610', 'Bank Fees'],
  ['825', 'Suspense / Review']
]

function formatMoney(amount: number, currency: string) {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency,
    currencyDisplay: 'narrowSymbol',
    minimumFractionDigits: 2
  }).format(Math.abs(amount))
}

function AccountMark() {
  return (
    <svg aria-hidden viewBox="0 0 20 20" className="size-4 fill-none stroke-current" strokeWidth="1.6">
      <path d="M3 6.5h14M4.5 6.5V5L10 2.5 15.5 5v1.5M5 8v5M9 8v5M13 8v5M3.5 14.5h13M2.5 17h15" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

export function BankReconciliation({
  transactions,
  onMatch,
  onAccountChange,
  onActionChange,
  className
}: BankReconciliationProps) {
  const [visible, setVisible] = React.useState(() => transactions.map((transaction) => transaction.id))
  const [leaving, setLeaving] = React.useState<string | null>(null)
  const [manualAccount, setManualAccount] = React.useState<Record<string, string>>({})
  const [actions, setActions] = React.useState<Record<string, ReconciliationAction>>(() => Object.fromEntries(transactions.map((transaction) => [transaction.id, transaction.action])))

  React.useEffect(() => {
    setVisible(transactions.map((transaction) => transaction.id))
    setActions(Object.fromEntries(transactions.map((transaction) => [transaction.id, transaction.action])))
  }, [transactions])

  const acceptMatch = (transaction: BankTransaction) => {
    const accountCode = manualAccount[transaction.id] ?? transaction.accountCode
    onMatch?.(transaction.id, accountCode)
    setLeaving(transaction.id)
    window.setTimeout(() => {
      setVisible((ids) => ids.filter((id) => id !== transaction.id))
      setLeaving(null)
    }, 240)
  }

  const remaining = transactions.filter((transaction) => visible.includes(transaction.id))

  return (
    <section aria-label="Bank reconciliation queue" className={cn('flex min-h-0 flex-col bg-card', className)}>
      <header className="flex min-h-10 items-center gap-4 border-b px-3">
        <div className="min-w-0 flex-1">
          <h2 className="text-[13px] font-semibold tracking-tight">Bank reconciliation</h2>
          <p className="text-[11px] text-muted-foreground">Coastal Bank · Operating account · 1142</p>
        </div>
        <div className="financial-data flex items-center gap-4 text-[11px]">
          <span><span className="text-muted-foreground">Statement </span>25 AUG 2026</span>
          <span><span className="text-muted-foreground">Unreconciled </span>{remaining.length}</span>
        </div>
      </header>

      <div className="scrollbar-thin min-h-0 overflow-auto">
        <div className="min-w-[900px]">
          <div className="grid h-8 grid-cols-12 items-center border-b bg-muted/65 text-[10px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
            <div className="col-span-5 px-3">Raw bank feed</div>
            <div className="col-span-2 px-3 text-center">Action</div>
            <div className="col-span-5 px-3">Suggested ledger entry</div>
          </div>

          {remaining.map((transaction, index) => {
            const isManual = transaction.state === 'manual'
            const isLeaving = leaving === transaction.id
            const selectedCode = manualAccount[transaction.id] ?? transaction.accountCode
            const selectedAccount = accountOptions.find(([code]) => code === selectedCode)

            return (
              <article
                key={transaction.id}
                aria-label={`${transaction.description}, ${formatMoney(transaction.amount, transaction.currency)}`}
                className={cn(
                  'grid min-h-[72px] grid-cols-12 border-b bg-card transition-[opacity,transform,max-height] duration-200 ease-out hover:bg-muted/20',
                  index === 0 && 'bg-info-muted/35',
                  isLeaving && '-translate-y-1 opacity-0'
                )}
              >
                <div className="col-span-5 grid min-w-0 grid-cols-[6.5rem_minmax(0,1fr)_8.5rem] items-center gap-3 border-r px-3 py-2">
                  <div>
                    <p className="financial-data text-[11px] text-muted-foreground">{transaction.date}</p>
                    <p className="financial-data mt-1 text-[10px] text-muted-foreground/75">{transaction.id}</p>
                  </div>
                  <p className="truncate text-[12px] font-semibold" title={transaction.description}>{transaction.description}</p>
                  <p className={cn('financial-data text-right text-[12px] font-semibold', transaction.amount < 0 ? 'text-destructive' : 'text-success')}>
                    {transaction.amount < 0 ? '−' : '+'}{formatMoney(transaction.amount, transaction.currency)}
                  </p>
                </div>

                <div className="relative col-span-2 flex items-center justify-center border-r px-3">
                  <span aria-hidden className="absolute left-0 right-0 top-1/2 h-px bg-border" />
                  <label className="relative bg-card px-2">
                    <span className="sr-only">Action for {transaction.description}</span>
                    <select
                      value={actions[transaction.id] ?? transaction.action}
                      onChange={(event) => {
                        const action = event.target.value as ReconciliationAction
                        setActions((current) => ({ ...current, [transaction.id]: action }))
                        onActionChange?.(transaction.id, action)
                      }}
                      className="h-7 appearance-none rounded-sm border bg-background pl-2 pr-6 text-[11px] font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    >
                      {(['Match', 'Transfer', 'Rule', 'Discuss'] as const).map((action) => <option key={action}>{action}</option>)}
                    </select>
                    <span aria-hidden className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-[9px] text-muted-foreground">▼</span>
                  </label>
                </div>

                <div className="col-span-5 flex min-w-0 items-center gap-3 px-3 py-2">
                  <span className="grid size-7 shrink-0 place-items-center rounded-sm bg-muted text-muted-foreground"><AccountMark /></span>
                  <div className="min-w-0 flex-1">
                    {isManual ? (
                      <div className="relative">
                        <button
                          type="button"
                          aria-haspopup="listbox"
                          aria-expanded="true"
                          className="flex h-7 w-full items-center gap-2 border bg-background px-2 text-left text-[11px] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                        >
                          <span className="financial-data rounded-sm bg-muted px-1.5 py-0.5 font-semibold">{selectedCode}</span>
                          <span className="truncate">{selectedAccount?.[1] ?? 'Select account'}</span>
                        </button>
                        <div role="listbox" aria-label={`Account for ${transaction.description}`} className="absolute left-0 top-8 z-20 w-full border bg-popover py-1 shadow-floating">
                          {accountOptions.slice(0, 3).map(([code, name]) => (
                            <button
                              key={code}
                              type="button"
                              role="option"
                              aria-selected={code === selectedCode}
                              onClick={() => {
                                setManualAccount((current) => ({ ...current, [transaction.id]: code }))
                                onAccountChange?.(transaction.id, code)
                              }}
                              className={cn('flex h-7 w-full items-center gap-2 px-2 text-left text-[11px] hover:bg-accent', code === selectedCode && 'bg-accent')}
                            >
                              <span className="financial-data w-8 text-muted-foreground">{code}</span><span>{name}</span>
                            </button>
                          ))}
                        </div>
                      </div>
                    ) : (
                      <>
                        <div className="flex min-w-0 items-center gap-2">
                          <span className="financial-data rounded-sm bg-muted px-1.5 py-0.5 text-[11px] font-semibold">{transaction.accountCode}</span>
                          <span className="truncate text-[12px] font-semibold">{transaction.accountName}</span>
                        </div>
                        <div className="mt-1 flex items-center gap-2">
                          <StatusBadge status={transaction.state === 'pending' ? 'pending' : 'draft'} dot={false}>
                            {transaction.state === 'pending' ? 'Needs review' : `AI suggestion · ${transaction.confidence}% match`}
                          </StatusBadge>
                        </div>
                      </>
                    )}
                  </div>
                  <Button
                    aria-label={`Accept match for ${transaction.description}`}
                    size="compact"
                    variant="success"
                    onClick={() => acceptMatch(transaction)}
                    className="w-10 shrink-0"
                  >
                    OK
                  </Button>
                </div>
              </article>
            )
          })}

          {remaining.length === 0 && (
            <div className="grid min-h-32 place-items-center border-b text-center">
              <div>
                <p className="text-sm font-semibold text-success">Account reconciled</p>
                <p className="mt-1 text-xs text-muted-foreground">All imported statement lines have been assigned.</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  )
}
