const accounts = [
  ['200', 'Sales Revenue'],
  ['221', 'Professional Services'],
  ['310', 'GST Clearing'],
  ['430', 'Software Subscriptions'],
  ['610', 'Bank Fees'],
  ['690', 'Travel & Accommodation']
] as const
const currencies = ['AUD', 'USD', 'EUR', 'GBP'] as const

const ledgerRows: LedgerRow[] = (() => {
  const balances: Record<(typeof currencies)[number], number> = { AUD: 248039.2, USD: 81042.4, EUR: 34900.1, GBP: 16502.8 }
  return Array.from({ length: 1600 }, (_, index) => {
    const currency = currencies[index % currencies.length]
    const account = accounts[index % accounts.length]
    const amount = Number((47.25 + ((index * 137.19) % 12840)).toFixed(2))
    const isDebit = index % 2 === 0
    balances[currency] += isDebit ? amount : -amount
    return {
      id: `GL-${String(928440 - index).padStart(7, '0')}`,
      date: `2026-08-${String(25 - (Math.floor(index / 4) % 24)).padStart(2, '0')}`,
      reference: index % 3 === 0 ? `INV-${String(1048 - (index % 48)).padStart(4, '0')}` : `JE-${String(7204 - (index % 900)).padStart(5, '0')}`,
      accountCode: account[0],
      accountName: account[1],
      currency,
      debit: isDebit ? amount : 0,
      credit: isDebit ? 0 : amount,
      balance: Number(balances[currency].toFixed(2))
    }
  })
})()

