'use client'

import * as React from 'react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type TaxCode = 'GST10' | 'VAT20' | 'TAXFREE'

export interface InvoiceLine {
  id: string
  itemCode: string
  description: string
  quantity: number
  unitPrice: number
  discountPercent: number
  accountCode: string
  accountName: string
  taxCode: TaxCode
}

export interface InvoiceMatrixProps {
  invoiceNumber: string
  currency?: 'AUD' | 'USD' | 'EUR' | 'GBP'
  lines: InvoiceLine[]
  activeAccountRow?: number
  onLineChange?: (lineId: string, field: keyof InvoiceLine, value: string | number) => void
  onAccountSelect?: (lineId: string, accountCode: string) => void
  onLineAdd?: (line: InvoiceLine) => void
  onSaveDraft?: (lines: InvoiceLine[]) => void
  onSave?: (lines: InvoiceLine[]) => void
  className?: string
}

const products = [
  ['DESIGN-01', 'Product design sprint'],
  ['RETAINER', 'Monthly advisory retainer'],
  ['LICENCE', 'Annual software licence'],
  ['TRAINING', 'On-site team training'],
  ['CUSTOM', 'Custom service line']
]

const accounts = [
  ['200', 'Sales Revenue'],
  ['221', 'Professional Services'],
  ['240', 'Subscription Revenue'],
  ['310', 'GST Collected']
]

const taxRates: Record<TaxCode, number> = { GST10: 0.1, VAT20: 0.2, TAXFREE: 0 }
const taxLabels: Record<TaxCode, string> = { GST10: 'GST 10%', VAT20: 'VAT 20%', TAXFREE: 'Tax free' }

function lineSubtotal(line: InvoiceLine) {
  return line.quantity * line.unitPrice * (1 - line.discountPercent / 100)
}

function formatMoney(value: number, currency: NonNullable<InvoiceMatrixProps['currency']>) {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency, currencyDisplay: 'narrowSymbol', minimumFractionDigits: 2 }).format(value)
}

function FieldLabel({ children }: { children: React.ReactNode }) {
  return <span className="sr-only">{children}</span>
}

export function InvoiceMatrix({
  invoiceNumber,
  currency = 'AUD',
  lines: initialLines,
  activeAccountRow,
  onLineChange,
  onAccountSelect,
  onLineAdd,
  onSaveDraft,
  onSave,
  className
}: InvoiceMatrixProps) {
  const [lines, setLines] = React.useState(initialLines)
  const [openAccountRow, setOpenAccountRow] = React.useState<number | null>(activeAccountRow ?? null)

  React.useEffect(() => setLines(initialLines), [initialLines])

  const updateLine = (index: number, field: keyof InvoiceLine, value: string | number) => {
    setLines((current) => current.map((line, lineIndex) => lineIndex === index ? { ...line, [field]: value } : line))
    onLineChange?.(lines[index].id, field, value)
  }

  const subtotal = lines.reduce((sum, line) => sum + lineSubtotal(line), 0)
  const taxByCode = lines.reduce<Record<TaxCode, number>>((totals, line) => {
    totals[line.taxCode] += lineSubtotal(line) * taxRates[line.taxCode]
    return totals
  }, { GST10: 0, VAT20: 0, TAXFREE: 0 })
  const taxTotal = Object.values(taxByCode).reduce((sum, value) => sum + value, 0)

  const addLine = () => {
    const line: InvoiceLine = {
      id: `line-${lines.length + 1}-${Date.now()}`,
      itemCode: 'CUSTOM',
      description: '',
      quantity: 1,
      unitPrice: 0,
      discountPercent: 0,
      accountCode: '200',
      accountName: 'Sales Revenue',
      taxCode: 'GST10'
    }
    setLines((current) => [...current, line])
    onLineAdd?.(line)
  }

  return (
    <section aria-label={`Invoice ${invoiceNumber}`} className={cn('relative flex min-h-0 flex-col border bg-card', className)}>
      <header className="flex min-h-10 items-center gap-4 border-b px-3">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <h2 className="text-[13px] font-semibold tracking-tight">New sales invoice</h2>
            <span className="financial-data text-[11px] text-muted-foreground">{invoiceNumber}</span>
          </div>
          <p className="text-[11px] text-muted-foreground">Northstar Architecture · Due 8 Sep 2026</p>
        </div>
        <span className="financial-data text-[11px] text-muted-foreground">Currency {currency}</span>
        <Button size="compact" variant="outline" type="button" onClick={() => onSaveDraft?.(lines)}>Save draft</Button>
        <Button size="compact" type="button" onClick={() => onSave?.(lines)}>Approve invoice</Button>
      </header>

      <div className="scrollbar-thin min-h-0 flex-1 overflow-auto pb-40">
        <div className="min-w-[1120px]">
          <div className="grid h-8 grid-cols-[130px_minmax(230px,1fr)_78px_122px_86px_190px_104px_132px] items-center border-b bg-muted text-[10px] font-semibold uppercase tracking-[0.06em] text-muted-foreground">
            <div className="h-full border-r px-2 py-2">Item / product</div>
            <div className="h-full border-r px-2 py-2">Description</div>
            <div className="h-full border-r px-2 py-2 text-right">Qty</div>
            <div className="h-full border-r px-2 py-2 text-right">Unit price</div>
            <div className="h-full border-r px-2 py-2 text-right">Disc %</div>
            <div className="h-full border-r px-2 py-2">Allocation account</div>
            <div className="h-full border-r px-2 py-2">Tax rate</div>
            <div className="h-full px-2 py-2 text-right">Line total</div>
          </div>

          {lines.map((line, index) => {
            const isAccountOpen = openAccountRow === index
            return (
              <div key={line.id} className="relative grid min-h-10 grid-cols-[130px_minmax(230px,1fr)_78px_122px_86px_190px_104px_132px] border-b bg-card text-[11px] hover:bg-muted/20">
                <label className="border-r p-1">
                  <FieldLabel>Item code, line {index + 1}</FieldLabel>
                  <select value={line.itemCode} onChange={(event) => updateLine(index, 'itemCode', event.target.value)} className="financial-data h-8 w-full border bg-background px-1.5 outline-none focus:ring-1 focus:ring-inset focus:ring-info">
                    {products.map(([code]) => <option key={code}>{code}</option>)}
                  </select>
                </label>

                <label className="border-r p-1">
                  <FieldLabel>Description, line {index + 1}</FieldLabel>
                  <textarea
                    rows={1}
                    value={line.description}
                    onChange={(event) => {
                      updateLine(index, 'description', event.target.value)
                      event.currentTarget.style.height = '32px'
                      event.currentTarget.style.height = `${event.currentTarget.scrollHeight}px`
                    }}
                    className="block min-h-8 w-full resize-none border-0 bg-transparent px-1.5 py-1.5 leading-5 outline-none focus:ring-1 focus:ring-inset focus:ring-info"
                  />
                </label>

                <label className="border-r p-1">
                  <FieldLabel>Quantity, line {index + 1}</FieldLabel>
                  <input type="number" min="0" step="1" value={line.quantity} onChange={(event) => updateLine(index, 'quantity', Number(event.target.value))} className="financial-data h-8 w-full border-0 bg-transparent px-1.5 text-right outline-none focus:ring-1 focus:ring-inset focus:ring-info" />
                </label>

                <label className="relative border-r p-1">
                  <FieldLabel>Unit price, line {index + 1}</FieldLabel>
                  <span aria-hidden className="financial-data absolute left-2 top-3 text-muted-foreground">$</span>
                  <input type="number" min="0" step="0.01" value={line.unitPrice} onChange={(event) => updateLine(index, 'unitPrice', Number(event.target.value))} className="financial-data h-8 w-full border-0 bg-transparent pl-4 pr-1 text-right outline-none focus:ring-1 focus:ring-inset focus:ring-info" />
                </label>

                <label className="relative border-r p-1">
                  <FieldLabel>Discount percentage, line {index + 1}</FieldLabel>
                  <input type="number" min="0" max="100" step="0.5" value={line.discountPercent} onChange={(event) => updateLine(index, 'discountPercent', Number(event.target.value))} className="financial-data h-8 w-full border-0 bg-transparent px-1.5 pr-4 text-right text-muted-foreground outline-none focus:ring-1 focus:ring-inset focus:ring-info" />
                  <span aria-hidden className="absolute right-2 top-3 text-muted-foreground">%</span>
                </label>

                <div className="relative border-r p-1">
                  <button
                    type="button"
                    aria-haspopup="listbox"
                    aria-expanded={isAccountOpen}
                    onClick={() => setOpenAccountRow(isAccountOpen ? null : index)}
                    className="flex h-8 w-full items-center gap-2 border bg-background px-1.5 text-left outline-none focus:ring-1 focus:ring-inset focus:ring-info"
                  >
                    <span className="financial-data rounded-sm bg-muted px-1 py-0.5 font-semibold">{line.accountCode}</span>
                    <span className="truncate">{line.accountName}</span>
                  </button>
                  {isAccountOpen && (
                    <div role="listbox" aria-label={`Allocation account, line ${index + 1}`} className="absolute left-1 right-1 top-10 z-30 border bg-popover py-1 shadow-floating">
                      <div className="border-b px-2 pb-1">
                        <input autoFocus aria-label="Search accounts" placeholder="Search accounts…" className="h-7 w-full border bg-background px-2 outline-none focus:ring-1 focus:ring-inset focus:ring-info" />
                      </div>
                      {accounts.map(([code, name]) => (
                        <button
                          key={code}
                          role="option"
                          aria-selected={code === line.accountCode}
                          type="button"
                          onClick={() => {
                            updateLine(index, 'accountCode', code)
                            updateLine(index, 'accountName', name)
                            onAccountSelect?.(line.id, code)
                            setOpenAccountRow(null)
                          }}
                          className={cn('flex h-7 w-full items-center gap-2 px-2 text-left hover:bg-accent', code === line.accountCode && 'bg-accent')}
                        >
                          <span className="financial-data w-8 text-muted-foreground">{code}</span><span>{name}</span>
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                <label className="border-r p-1">
                  <FieldLabel>Tax rate, line {index + 1}</FieldLabel>
                  <select value={line.taxCode} onChange={(event) => updateLine(index, 'taxCode', event.target.value as TaxCode)} className="h-8 w-full border-0 bg-transparent px-1 outline-none focus:ring-1 focus:ring-inset focus:ring-info">
                    {(Object.keys(taxLabels) as TaxCode[]).map((code) => <option key={code} value={code}>{taxLabels[code]}</option>)}
                  </select>
                </label>

                <output aria-label={`Line ${index + 1} total`} className="financial-data flex h-10 items-center justify-end px-2 font-semibold">
                  {formatMoney(lineSubtotal(line), currency)}
                </output>
              </div>
            )
          })}

          <div className="flex h-9 items-center border-b px-2">
            <button type="button" onClick={addLine} className="text-[11px] font-semibold text-info hover:underline">+ Add line item</button>
            <span className="ml-auto text-[10px] text-muted-foreground">Tab moves through every line-item field</span>
          </div>
        </div>
      </div>

      <footer className="absolute bottom-0 right-0 z-20 w-[364px] border-l border-t bg-card">
        <div className="grid grid-cols-[1fr_132px] text-[11px]">
          <span className="border-b px-3 py-2 text-muted-foreground">Subtotal</span>
          <span className="financial-data border-b px-3 py-2 text-right">{formatMoney(subtotal, currency)}</span>
          {taxByCode.GST10 > 0 && <><span className="border-b px-3 py-2 text-muted-foreground">GST 10%</span><span className="financial-data border-b px-3 py-2 text-right">{formatMoney(taxByCode.GST10, currency)}</span></>}
          {taxByCode.VAT20 > 0 && <><span className="border-b px-3 py-2 text-muted-foreground">VAT 20%</span><span className="financial-data border-b px-3 py-2 text-right">{formatMoney(taxByCode.VAT20, currency)}</span></>}
          <span className="px-3 py-3 text-sm font-semibold">Total due</span>
          <strong className="financial-data px-3 py-3 text-right text-lg tracking-tight">{formatMoney(subtotal + taxTotal, currency)}</strong>
        </div>
      </footer>
    </section>
  )
}
